{"command":"cd /work/workspace/documents && (which pdftotext && pdftotext employment_agreement_excerpt.pdf - ) 2>&1 | head -80; echo "---PY---"; python3 -c "
import re,zlib
data=open('employment_agreement_excerpt.pdf','rb').read()
print(len(data))
# find streams
for m in re.finditer(rb'stream\r?\n(.*?)endstream', data, re.S):
    s=m.group(1)
    try:
        d=zlib.decompress(s)
        print(d[:4000])
    except Exception as e:
        print('raw', s[:200])
""}

